#define DT_DRV_COMPAT bosch_bmi160

#include <zephyr/device.h>
#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/drivers/spi.h>
#include <zephyr/drivers/spi_emul.h>
#include <zephyr/logging/log.h>

#include "bmi160.h"

LOG_MODULE_REGISTER(bmi160_emul, CONFIG_SENSOR_LOG_LEVEL);

#define BMI160_EMUL_REG_COUNT (BMI160_CMD_REG + 1)

/**
 * @brief Structure for holding the emulator's data
 *
 * @param chip_id The chip ID of this emulated device
 * @param regs The registers of this emulated device
 * @param i2c The I2C emulation API data
 * @param spi The SPI emulation API data
 */
struct bmi160_emul_data {
	uint8_t chip_id;
	uint8_t regs[BMI160_EMUL_REG_COUNT];
	struct i2c_emul_api i2c;
	struct spi_emul_api spi;
};

static struct bmi160_emul_data *bmi160_emul_get_data(struct emul *target)
{
	return target->data;
}

static int bmi160_emul_reg_read(struct emul *target, int reg, uint8_t *val)
{
	struct bmi160_emul_data *data = bmi160_emul_get_data(target);

	if (reg >= BMI160_EMUL_REG_COUNT) {
		return -EINVAL;
	}

	switch (reg) {
	case BMI160_CHIP_ID_ADDR:
		*val = data->chip_id;
		break;
	default:
		*val = data->regs[reg];
		break;
	}

	return 0;
}

static int bmi160_emul_reg_write(struct emul *target, int reg, uint8_t val)
{
	struct bmi160_emul_data *data = bmi160_emul_get_data(target);

	if (reg >= BMI160_EMUL_REG_COUNT) {
		return -EINVAL;
	}

	data->regs[reg] = val;

	return 0;
}

static int bmi160_emul_handle_read(struct emul *target, int reg, struct i2c_msg *msg)
{
	int ret;

	for (int i = 0; i < msg->len; i++) {
		ret = bmi160_emul_reg_read(target, reg + i, &msg->buf[i]);
		if (ret) {
			return ret;
		}
	}

	return 0;
}

static int bmi160_emul_handle_write(struct emul *target, int reg, struct i2c_msg *msg)
{
	int ret;

	for (int i = 0; i < msg->len; i++) {
		ret = bmi160_emul_reg_write(target, reg + i, msg->buf[i]);
		if (ret) {
			return ret;
		}
	}

	return 0;
}

static int bmi160_emul_transfer_i2c(struct emul *target, struct i2c_msg *msgs, int num_msgs,
				    int addr)
{
	int reg;

	if (num_msgs == 1) {
		if (msgs[0].flags & I2C_MSG_READ) {
			LOG_ERR("Unexpected read");
			return -EIO;
		}
		reg = msgs[0].buf[0];
		msgs[0].buf++;
		msgs[0].len--;
		return bmi160_emul_handle_write(target, reg, &msgs[0]);
	}

	if (num_msgs == 2) {
		if (msgs[0].flags & I2C_MSG_READ) {
			LOG_ERR("Unexpected read");
			return -EIO;
		}

		if (msgs[0].len != 1) {
			LOG_ERR("Unexpected message length: %d", msgs[0].len);
			return -EIO;
		}

		if (!(msgs[1].flags & I2C_MSG_READ)) {
			LOG_ERR("Unexpected write");
			return -EIO;
		}

		reg = msgs[0].buf[0];
		return bmi160_emul_handle_read(target, reg, &msgs[1]);
	}

	LOG_ERR("Unexpected number of messages: %d", num_msgs);
	return -EIO;
}

static int bmi160_emul_transfer_spi(struct emul *target, const struct spi_config *config,
				    const struct spi_buf_set *tx_bufs,
				    const struct spi_buf_set *rx_bufs)
{
	const struct spi_buf *tx_buf;
	const struct spi_buf *rx_buf;
	uint8_t reg;
	bool is_read;
	int ret;

	tx_buf = tx_bufs->bufs;
	reg = *(uint8_t *)tx_buf->buf;
	is_read = reg & BMI160_SPI_READ_BIT;
	reg &= ~BMI160_SPI_READ_BIT;

	if (is_read) {
		/* Read data */
		if (rx_bufs == NULL) {
			return 0;
		}
		/* First byte is ignored */
		rx_buf = rx_bufs->bufs + 1;

		for (int i = 0; i < rx_bufs->count - 1; i++) {
			for (int j = 0; j < rx_buf->len; j++) {
				ret = bmi160_emul_reg_read(target, reg + j,
							   &((uint8_t *)rx_buf->buf)[j]);
				if (ret) {
					return ret;
				}
			}
			reg += rx_buf->len;
			rx_buf++;
		}
	} else {
		/* Write data */
		/* Second tx buffer is data */
		tx_buf = tx_bufs->bufs + 1;

		for (int i = 0; i < tx_bufs->count - 1; i++) {
			for (int j = 0; j < tx_buf->len; j++) {
				ret = bmi160_emul_reg_write(target, reg + j,
							    ((uint8_t *)tx_buf->buf)[j]);
				if (ret) {
					return ret;
				}
			}
			reg += tx_buf->len;
			tx_buf++;
		}
	}

	return 0;
}

static int bmi160_emul_init(const struct emul *target)
{
	struct bmi160_emul_data *data = bmi160_emul_get_data(target);

	data->chip_id = BMI160_CHIP_ID;

	return 0;
}

#define BMI160_EMUL_DEFINE(n)                                                                      \
	static struct bmi160_emul_data bmi160_emul_data_##n;                                        \
	                                                                                                 \
	static const struct i2c_emul_api bmi160_emul_api_i2c_##n = {                                \
		.transfer = bmi160_emul_transfer_i2c,                                              \
	};                                                                                         \
	                                                                                                 \
	static const struct spi_emul_api bmi160_emul_api_spi_##n = {                                \
		.transfer = bmi160_emul_transfer_spi,                                              \
	};                                                                                         \
	                                                                                                 \
	EMUL_DT_INST_DEFINE(n, bmi160_emul_init, &bmi160_emul_data_##n, NULL,                       \
			    &bmi160_emul_api_i2c_##n, &bmi160_emul_api_spi_##n)

DT_INST_FOREACH_STATUS_OKAY(BMI160_EMUL_DEFINE)
